"""Business questions shared by every structured document extraction."""
QUESTIONS = {
    "franchise": "Какие виды франшизы предусмотрены? Как определяется размер, когда применяется и от чего зависит? Не выдавай пример расчёта за обязательный тариф.",
    "without_certificates": "Для каких повреждений разрешена выплата без документов компетентных органов? Укажи лимит суммы, количество обращений, исключения и условия. Не путай с отсутствием ключей при угоне.",
    "gap": "Предусмотрено ли возмещение разницы из-за уменьшения стоимости автомобиля (GAP)? При каких событиях, в каком размере, как отдельная опция или часть покрытия?",
    "total_loss": "Как определяется полная гибель автомобиля? Укажи процент, базу расчёта, строгое или включающее сравнение и возможность иного порога по договору.",
    "self_ignition": "Как урегулируется повреждение автомобиля при самовозгорании без внешнего воздействия? Проанализируй определение пожара, условие внешнего воздействия и исключения внутренних неисправностей. Объясни предел вывода, если слово «самовозгорание» не используется.",
    "terrorism": "Как урегулируется ущерб автомобилю от террористического акта? Если он не назван прямо, проанализируй противоправные действия третьих лиц, поджог, подрыв и исключения. Не приравнивай их автоматически к покрытию терроризма; 115-ФЗ не отвечает на этот вопрос.",
    "drone": "Как происходит выплата при повреждении автомобиля БПЛА или его обломками? Если БПЛА не назван прямо, проанализируй пункты о падении предметов, противоправных действиях, исключениях и общем порядке урегулирования. Различай гражданские и военные аппараты; укажи, что правила не позволяют установить однозначно.",
    "tow_truck": "Когда оплачивается эвакуация автомобиля, куда, с каким денежным лимитом или расстоянием? Нужны ли согласование и невозможность движения своим ходом?",
    "repair_type": "Какие формы возмещения доступны: деньги, ремонт на СТОА страховщика, страхователя или у дилера? Кто выбирает, от чего зависит выбор и какие ограничения установлены?",
    "payment_terms": "Каков срок выплаты или выдачи направления на ремонт, с какого события он отсчитывается? Различай рабочие и календарные дни, выплату и рассмотрение заявления, хищение и ущерб; укажи основания продления.",
}


def question_prompt():
    return "\n".join(f"{key}: {question}" for key, question in QUESTIONS.items())
